-- Restore the model year lost from bike names (1 oct 2026).
--
-- nameAfterSave rebuilt a bike name as "model size colour" and dropped the year
-- (fixed in c76658bc). No column holds the year: the name is its only home, so
-- it is put back where the AS400 writes it, between size and colour.
-- Rafael, 1 oct 2026: "as400 gana, despues la uno" — the year comes from
-- sku_metadata.as400_description, else from another row of the same SKU.
-- Inactive rows are included (they show in the ghost trail and the history);
-- rows whose size cannot be placed safely (compound sizes, broken names) and
-- rows with no year anywhere are left alone. Each row is touched only if its
-- name is still exactly the previewed one, and every change is kept in
-- item_name_year_restores (append-only) so it can be undone.

create table if not exists public.item_name_year_restores (
  id bigserial primary key,
  inventory_id bigint not null,
  sku text not null,
  old_item_name text,
  new_item_name text not null,
  year int not null,
  source text not null,
  created_at timestamptz not null default now()
);

comment on table public.item_name_year_restores is
  'Bike names given back their model year on 1 oct 2026, old and new. Append-only.';

alter table public.item_name_year_restores enable row level security;

drop policy if exists "admins read item name year restores" on public.item_name_year_restores;
create policy "admins read item name year restores"
  on public.item_name_year_restores for select
  to authenticated
  using (public.is_admin());

