  update public.inventory i
     set item_name = p.new_name
    from plan p
   where i.id = p.inventory_id
     and i.sku = p.sku
     and i.item_name is not distinct from p.old_name
  returning i.id, p.sku, p.old_name, p.new_name, p.year, p.source
)
insert into public.item_name_year_restores (inventory_id, sku, old_item_name, new_item_name, year, source)
select id, sku, old_name, new_name, year, source from applied;
